import sys,json
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]));sys.path.insert(0,str(Path(__file__).resolve().parent))
from gongbi_training.runtime import configure,LAB
configure()
import numpy as np
from PIL import Image
from guohua_boundary_reference_20261116 import ROOT,read,sha,write
def main():
 refs=read(ROOT/'reviewed_references.json');res=read(ROOT/'reviewed_results.json');assert sha(ROOT/'reviewed_references.json')==res['reference_sha256'];assert len(refs['cases'])==4
 for c in refs['cases']:
  assert sha(c['image'])==c['image_sha256']
  mask=np.array(Image.open(ROOT/'masks'/(c['id']+'_reviewed_sparse_core.png')));assert set(np.unique(mask))<={1,2,255};assert (mask==255).any()
  for r in c['regions']:
   assert all(0<=x<c['size'][0] and 0<=y<c['size'][1] for x,y in r['points']);assert (r['object']=='unknown')==(r['kind']=='uncertain_polygon')
  result=next(x for x in res['records'] if x['id']==c['id'])
  assert all(r['scores'] is None for r in result['regions'] if r['object']=='unknown')
 paths={'pilot':LAB/'guohua_objects_pilot_20261112/context_object_head.pt','expanded':LAB/'guohua_objects_v2_20261113/expanded_control.pt','core_loss':LAB/'guohua_objects_v3_20261116/core_balanced.pt'}
 assert all(sha(path)==res['checkpoint_hashes'][name] for name,path in paths.items())
 review=read(ROOT/'reference_review.json');assert sha(ROOT/'references.json')==review['original_reference_sha256'];assert sha(ROOT/'results.json')==review['original_results_sha256']
 checks=dict(reference_hash_matches=True,source_hashes_match=True,frozen_checkpoints_unchanged=True,original_annotations_and_predictions_preserved=True,coordinates_in_image_bounds=True,sparse_core_void_preserved=True,unknown_regions_excluded_from_scores=True,new_training=False,model_adopted=False,expert_reviewed=False,independent_test=False,robot_connected=False)
 write('verification.json',checks)
 page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>树石边界参考与冻结模型诊断</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f1e8;color:#294735;font:16px/1.7 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1500px;margin:auto;padding:24px}h1{font-size:29px}.note{padding:15px;background:#fff8e8;border-left:5px solid #b37842}.warn{color:#875238}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.card{min-width:0;padding:10px;background:#fffdf8;border:1px solid #d4d7ca}img,canvas{display:block;max-width:100%;height:auto;margin:auto}select{max-width:100%;width:650px;padding:8px;font:inherit}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:9px;text-align:left;border-bottom:1px solid #cdd3c6}button{font:inherit;padding:6px;margin:4px;cursor:pointer}a{color:#236b61}@media(max-width:700px){main{padding:14px}.grid{grid-template-columns:1fr}h1{font-size:24px}}</style><main><small>2026-11-16 · 补参考与错误定位 · 未训练新模型</small><h1>先分清对象归属，再补墨带与完整笔触</h1><p class="note"><b>完成四个局部、25处助手核查参考。</b>三处来自已用于旧训练的作品，另一处是用户指出的树叶案例；均不构成新独立测试。内部对象参考、淡轮廓附近的粗定位、树石交叠待定区分别保存。此页没有新提取模型或实画效果。</p><p class="warn">这些参考不是专家真值、精确叶片/墨带边界、真实中心线或逐笔归属。待定区不作背景负例，也不强行标皴笔。已有模型权重和结果未变，没有用参考修饰模型输出。</p><h2>1. 原图、助手参考与原始预测</h2><select id="case"></select><p id="scope"></p><div class="grid"><div class="card"><b>原图</b><img id="input"></div><div class="card"><b>助手参考，非模型输出</b><img id="reference"></div><div class="card"><b>上轮扩充数据模型</b><img id="expanded"></div><div class="card"><b>失败的边界／核心模型</b><img id="core_loss"></div></div><p id="refnote">仅有稀疏对象参考，无完整对象边界。</p><p>参考棕=山石、绿=树木、粉=交叠待定。模型棕=山石、绿=树木、灰蓝=其他。对象内部可以包括纸色留白，不能直接把对象区域当作墨迹。</p><details><summary>更早的对象模型预测</summary><img id="pilot"></details><h2>2. 逐处检查：点击行高亮参考位置</h2><div class="grid"><div class="card"><b>原图上的所选参考</b><canvas id="focus"></canvas></div><div class="card" style="grid-column:span 3"><p id="regionnote"></p><div class="scroll"><table><thead><tr><th>区域与参考类型</th><th>更早模型</th><th>上轮扩充</th><th>失败新约束</th></tr></thead><tbody id="metrics"></tbody></table></div></div></div><p>表内数字仅是模型类别与助手所选区域的对应比例，不是专家准确率、墨迹召回或笔画恢复率。轮廓走廊包含附近纸面，不能称作逐像素线条真值。待定区完全不计分；不同案例不汇总成一个精度。</p><h2>3. 四局部总览</h2><img src="reference_comparison.jpg"><h2>4. 本轮完成与下一步</h2><p>本轮补的是稀疏参考和逐区域诊断，没有追加同样的训练。对象内部与可见轮廓、交叠待定区已分开。下一步先扩充并复核这些边界参考，再用一部分作弱监督；保留另一些完整作品作检查，不能拿同图裁剪证明泛化。参考未核查部分继续保留未知。</p><p>确认对象后，才补山石中的真实皴笔墨带、近邻纸面、交叉归属和收笔；不从树冠区域自动生成皴笔标签。皴法辨识仍未通过，树木画法训练保持关闭，未连接机械臂。</p><p><a href="references.json">冻结参考、坐标与不确定性</a> · <a href="results.json">逐区域诊断</a> · <a href="verification.json">检查记录</a></p></main><script>let D,R;const $=s=>document.getElementById(s),A=['pilot','expanded','core_loss'],C={rock:'#b7864b',tree:'#2da15b',unknown:'#c440a2'},pct=x=>(x*100).toFixed(1)+'%';let source=new Image();function focus(j){let c=R.cases[$('case').selectedIndex],r=c.regions[j],v=$('focus');v.width=c.size[0];v.height=c.size[1];let ctx=v.getContext('2d');ctx.drawImage(source,0,0);ctx.beginPath();r.points.forEach(([x,y],k)=>k?ctx.lineTo(x,y):ctx.moveTo(x,y));if(r.kind!=='contour_corridor')ctx.closePath();ctx.strokeStyle=C[r.object];ctx.fillStyle=C[r.object]+'55';ctx.lineWidth=r.corridor_width_px||2;if(r.kind!=='contour_corridor')ctx.fill();ctx.stroke();$('regionnote').textContent=r.name+'：'+r.note+'。参考类型：'+r.kind+'；对象：'+r.object;}function show(){let i=$('case').selectedIndex,c=D.records[i];$('input').src=c.input;$('reference').src=c.reference;for(let a of A)$(a).src=c.predictions[a];$('scope').textContent=c.id+' / '+c.prior_use;$('metrics').innerHTML='';for(let [j,r] of c.regions.entries()){let tr=document.createElement('tr');let td=document.createElement('td'),button=document.createElement('button');button.textContent=r.name;button.onclick=()=>focus(j);td.append(button);let small=document.createElement('small');small.textContent=' '+r.object+' / '+r.kind;td.append(small);tr.append(td);for(let a of A){let t=document.createElement('td');t.textContent=r.scores?pct(r.scores[a]):'待定，不计分';tr.append(t)}$('metrics').append(tr)}source.onload=()=>focus(0);source.src=c.input;}Promise.all([fetch('results.json').then(r=>r.json()),fetch('references.json').then(r=>r.json())]).then(([d,r])=>{D=d;R=r;for(let c of d.records){let o=document.createElement('option');o.textContent=c.id;$('case').append(o)}$('case').onchange=show;show();window.reportReady=true});</script></html>'''
 page=page.replace('25处助手核查参考。','25处候选参考，其中20处对象归属参考、5处待定。').replace('<h2>1. 原图','<p class="warn">二次核查将一处松树干／岩面难分区域降为待定，已停止计分；该调整发生于查看预测后，只用于修正参考，不能称预注册测试。原始参考、原始结果及变更记录均保留。</p><h2>1. 原图').replace("fetch('results.json')","fetch('reviewed_results.json')").replace("fetch('references.json')","fetch('reviewed_references.json')").replace('href="references.json"','href="reviewed_references.json"').replace('href="results.json"','href="reviewed_results.json"').replace('冻结参考、坐标与不确定性','复核参考、坐标与不确定性').replace('</main>','<p><a href="reference_review.json">核查变更记录</a> · <a href="references.json">原始冻结参考</a> · <a href="results.json">原始未修订结果</a></p></main>')
 (ROOT/'index.html').write_text(page,encoding='utf8')
 # Reuse read-only server implementation; replace the allowlist, not the filesystem scope.
 source=Path(__file__).with_name('serve_guohua_objects_v2_20261113.py').read_text('utf8').replace('guohua_objects_v2_20261113','guohua_boundary_reference_20261116');start=source.index('ALLOWED={');end=source.index('\nALLOWED.update',start);source=source[:start]+"ALLOWED={'index.html','references.json','results.json','reviewed_references.json','reviewed_results.json','reference_review.json','verification.json','reference_comparison.jpg'}"+source[end:];(ROOT/'serve_report.py').write_text(source.replace('str(Path(__file__).resolve().parents[1])',repr(str(Path(__file__).resolve().parents[1]))),encoding='utf8')
 checker=Path(__file__).with_name('check_guohua_objects_v2_view_20261113.py').read_text('utf8').replace('guohua_objects_v2_20261113','guohua_boundary_reference_20261116').replace(')==27',')==4').replace(')==6',')==7').replace(';assert js("document.querySelectorAll(\'#works tr\').length")==4','').replace('range(27)','range(4)').replace("['protocol.json','results.json','selection_before_download.json','source_checked_cunfa_concepts.json','verification.json']","['references.json','results.json','verification.json']").replace('all27_observations_switch_and_load','all4_observations_switch_and_load').replace('metrics_six_rows','initial_seven_regions').replace('work_metrics_four_rows=True,','')
 # Also exercise every region highlight and preserve the source image geometry.
 checker=checker.replace("assert requests.post(url,timeout=5).status_code==405", "assert js('document.getElementById(\"focus\").width===410');assert js('document.querySelectorAll(\"#metrics button\").length')==7\n for j in range(7):js(f'document.querySelectorAll(\"#metrics button\")[{j}].click()')\n assert requests.post(url,timeout=5).status_code==405")
 (ROOT/'check_report.py').write_text(checker.replace('str(Path(__file__).resolve().parents[1])',repr(str(Path(__file__).resolve().parents[1]))),encoding='utf8');print(json.dumps(checks),flush=True)
if __name__=='__main__':main()
